1	package fleet
2	
3	import (
4		"encoding/json"
5		"errors"
6		"time"
7	)
8	
9	// Config delivery lets a fleet operator publish complete JSON configurations
10	// to a registered device. A simulated device reads only the latest target
11	// version, applies it, and reports a success or failure receipt. Versions are
12	// per-device integers starting at 1; before the first publish both the target
13	// and the applied version read as 0.
14	//
15	// History is immutable: publishing never edits an old version, so rolling back
16	// means re-publishing the old content as a new version. Every device keeps its
17	// own versions, publish-request deduplication records and receipts.
18	
19	// ConfigView is one published configuration version with its complete content.
20	type ConfigView struct {
21		Version     int64           `json:"version"`
22		Content     json.RawMessage `json:"config"`
23		PublishedAt time.Time       `json:"publishedAt"`
24	}
25	
26	// ConfigPublishResult is returned (and stored for idempotent retries) by a
27	// successful publish.
28	type ConfigPublishResult struct {
29		RequestID   string          `json:"requestId"`
30		Version     int64           `json:"version"`
31		Content     json.RawMessage `json:"config"`
32		PublishedAt time.Time       `json:"publishedAt"`
33	}
34	
35	// ConfigReceipt is one device-reported application outcome, retained in
36	// receive order.
37	type ConfigReceipt struct {
38		ReceiptID  string    `json:"receiptId"`
39		Version    int64     `json:"version"`
40		Success    bool      `json:"success"`
41		Reason     string    `json:"reason,omitempty"`
42		ReceivedAt time.Time `json:"receivedAt"`
43	}
44	
45	// ConfigStatus summarises where a device stands.
46	type ConfigStatus struct {
47		TargetVersion  int64  `json:"targetVersion"`
48		AppliedVersion int64  `json:"appliedVersion"`
49		FailureReason  string `json:"-"`
50	}
51	
52	var (
53		// ErrConfigConflict covers a stale publish base, a publish requestId reused
54		// with a different base or content, a stale/contradictory receipt, and a
55		// receiptId reused with different content.
56		ErrConfigConflict = errors.New("configuration conflict")
57		// ErrConfigVersionUnknown is reported for a receipt for a version that was
58		// never published to the device.
59		ErrConfigVersionUnknown = errors.New("configuration version unknown")
60	)
61	
62	type publishedConfig struct {
63		content     json.RawMessage
64		publishedAt time.Time
65	}
66	
67	// storedPublish remembers a committed publish so the same requestId can be
68	// recognised as an idempotent retry or a conflicting reuse.
69	type storedPublish struct {
70		baseVersion int64
71		content     json.RawMessage
72		result      ConfigPublishResult
73	}
74	
75	type configState struct {
76		versions  []publishedConfig        // index + 1 is the version number
77		applied   int64                    // highest successfully applied version
78		publishes map[string]storedPublish // requestId -> first publish
79		receipts  []ConfigReceipt          // receive order
80		byReceipt map[string]ConfigReceipt // receiptId -> first receipt
81	}
82	
83	func newConfigState() *configState {
84		return &configState{
85			publishes: make(map[string]storedPublish),
86			byReceipt: make(map[string]ConfigReceipt),
87		}
88	}
89	
90	// ensureConfig lazily attaches config state to a device; callers must hold the
91	// store lock (write mode when allocate is wanted).
92	func (state *deviceState) ensureConfig() *configState {
93		if state.config == nil {
94			state.config = newConfigState()
95		}
96		return state.config
97	}
98	
99	// PublishConfig applies one optimistic-concurrency publish.
100	//
101	// A requestId already committed on this device is an idempotent retry when the
102	// base and content match (the first result is returned with repeat=true) and a
103	// conflict otherwise. A fresh requestId only creates a version when baseVersion
104	// equals the current target; the loser of a concurrent race therefore gets
105	// ErrConfigConflict without consuming a version.
106	func (s *Store) PublishConfig(id, requestID string, baseVersion int64, content json.RawMessage) (ConfigPublishResult, bool, error) {
107		s.mu.Lock()
108		defer s.mu.Unlock()
109		state, ok := s.devices[id]
110		if !ok {
111			return ConfigPublishResult{}, false, ErrDeviceNotFound
112		}
113		cfg := state.ensureConfig()
114	
115		if previous, seen := cfg.publishes[requestID]; seen {
116			if previous.baseVersion != baseVersion || !sameJSON(previous.content, content) {
117				return ConfigPublishResult{}, false, ErrConfigConflict
118			}
119			return clonePublishResult(previous.result), true, nil
120		}
121	
122		target := int64(len(cfg.versions))
123		if baseVersion != target {
124			return ConfigPublishResult{}, false, ErrConfigConflict
125		}
126		version := target + 1
127		now := s.now().UTC()
128		stored := storedPublish{
129			baseVersion: baseVersion,
130			content:     cloneJSON(content),
131			result: ConfigPublishResult{
132				RequestID:   requestID,
133				Version:     version,
134				Content:     cloneJSON(content),
135				PublishedAt: now,
136			},
137		}
138		if s.wal != nil {
139			if err := s.wal.appendRecord(recConfigPublish, walConfigPublish{
140				DeviceID:    id,
141				RequestID:   requestID,
142				BaseVersion: baseVersion,
143				Version:     version,
144				Content:     cloneJSON(content),
145				PublishedAt: now,
146			}); err != nil {
147				return ConfigPublishResult{}, false, storageUnavailable(err)
148			}
149		}
150		cfg.versions = append(cfg.versions, publishedConfig{
151			content:     cloneJSON(content),
152			publishedAt: now,
153		})
154		cfg.publishes[requestID] = stored
155		return clonePublishResult(stored.result), false, nil
156	}
157	
158	// PendingConfig returns the latest target version when the device has not yet
159	// applied it. It returns ok=false when nothing was ever published or the
160	// latest version is already applied; reads never mutate state and old versions
161	// skipped by a newer target are not delivered individually.
162	func (s *Store) PendingConfig(id string) (ConfigView, bool, error) {
163		s.mu.RLock()
164		defer s.mu.RUnlock()
165		state, ok := s.devices[id]
166		if !ok {
167			return ConfigView{}, false, ErrDeviceNotFound
168		}
169		if state.config == nil {
170			return ConfigView{}, false, nil
171		}
172		cfg := state.config
173		target := int64(len(cfg.versions))
174		if target == 0 || cfg.applied >= target {
175			return ConfigView{}, false, nil
176		}
177		latest := cfg.versions[target-1]
178		return ConfigView{
179			Version:     target,
180			Content:     cloneJSON(latest.content),
181			PublishedAt: latest.publishedAt,
182		}, true, nil
183	}
184	
185	// RecordConfigReceipt validates and stores one application receipt.
186	//
187	// A repeated receiptId with identical version/result/reason returns the first
188	// receipt (repeat=true); a reused receiptId with different content conflicts.
189	// A version that was never published is ErrConfigVersionUnknown; a new receipt
190	// below the applied version and a failure for an already applied version
191	// conflict. Success advances the applied version (a success lagging behind the
192	// target is recorded and advances only up to its own version); failure never
193	// advances, so the latest target stays readable for a retry.
194	func (s *Store) RecordConfigReceipt(id, receiptID string, version int64, success bool, reason string) (ConfigReceipt, bool, error) {
195		s.mu.Lock()
196		defer s.mu.Unlock()
197		state, ok := s.devices[id]
198		if !ok {
199			return ConfigReceipt{}, false, ErrDeviceNotFound
200		}
201		cfg := state.ensureConfig()
202	
203		// A reason belongs to failures only; a successful result never carries one.
204		if success {
205			reason = ""
206		}
207	
208		if previous, seen := cfg.byReceipt[receiptID]; seen {
209			if previous.Version != version || previous.Success != success || previous.Reason != reason {
210				return ConfigReceipt{}, false, ErrConfigConflict
211			}
212			return previous, true, nil
213		}
214	
215		if version < 1 || version > int64(len(cfg.versions)) {
216			return ConfigReceipt{}, false, ErrConfigVersionUnknown
217		}
218		if version < cfg.applied {
219			return ConfigReceipt{}, false, ErrConfigConflict
220		}
221		if !success && version <= cfg.applied {
222			// The version already succeeded; it cannot fail afterwards.
223			return ConfigReceipt{}, false, ErrConfigConflict
224		}
225	
226		now := s.now().UTC()
227		receipt := ConfigReceipt{
228			ReceiptID:  receiptID,
229			Version:    version,
230			Success:    success,
231			Reason:     reason,
232			ReceivedAt: now,
233		}
234		if s.wal != nil {
235			if err := s.wal.appendRecord(recConfigReceipt, walConfigReceipt{
236				DeviceID:   id,
237				ReceiptID:  receiptID,
238				Version:    version,
239				Success:    success,
240				Reason:     reason,
241				ReceivedAt: now,
242			}); err != nil {
243				return ConfigReceipt{}, false, storageUnavailable(err)
244			}
245		}
246		cfg.receipts = append(cfg.receipts, receipt)
247		cfg.byReceipt[receiptID] = receipt
248		if success && version > cfg.applied {
249			cfg.applied = version
250		}
251		return receipt, false, nil
252	}
253	
254	// ListConfigs returns every published version in ascending version order, each
255	// with its complete content.
256	func (s *Store) ListConfigs(id string) ([]ConfigView, error) {
257		s.mu.RLock()
258		defer s.mu.RUnlock()
259		state, ok := s.devices[id]
260		if !ok {
261			return nil, ErrDeviceNotFound
262		}
263		if state.config == nil {
264			return []ConfigView{}, nil
265		}
266		cfg := state.config
267		views := make([]ConfigView, 0, len(cfg.versions))
268		for i, published := range cfg.versions {
269			views = append(views, ConfigView{
270				Version:     int64(i + 1),
271				Content:     cloneJSON(published.content),
272				PublishedAt: published.publishedAt,
273			})
274		}
275		return views, nil
276	}
277	
278	// ListConfigReceipts returns the device's receipts in first-receive order.
279	func (s *Store) ListConfigReceipts(id string) ([]ConfigReceipt, error) {
280		s.mu.RLock()
281		defer s.mu.RUnlock()
282		state, ok := s.devices[id]
283		if !ok {
284			return nil, ErrDeviceNotFound
285		}
286		if state.config == nil {
287			return []ConfigReceipt{}, nil
288		}
289		return append([]ConfigReceipt(nil), state.config.receipts...), nil
290	}
291	
292	// ConfigStatus returns target/applied versions plus the reason of the most
293	// recent failing receipt that still concerns an unapplied version.
294	func (s *Store) GetConfigStatus(id string) (ConfigStatus, error) {
295		s.mu.RLock()
296		defer s.mu.RUnlock()
297		state, ok := s.devices[id]
298		if !ok {
299			return ConfigStatus{}, ErrDeviceNotFound
300		}
301		status := ConfigStatus{}
302		if state.config == nil {
303			return status, nil
304		}
305		cfg := state.config
306		status.TargetVersion = int64(len(cfg.versions))
307		status.AppliedVersion = cfg.applied
308		for i := len(cfg.receipts) - 1; i >= 0; i-- {
309			receipt := cfg.receipts[i]
310			if !receipt.Success && receipt.Version > cfg.applied {
311				status.FailureReason = receipt.Reason
312				break
313			}
314		}
315		return status, nil
316	}
317	
318	func clonePublishResult(result ConfigPublishResult) ConfigPublishResult {
319		result.Content = cloneJSON(result.Content)
320		return result
321	}
322	
323	func cloneJSON(raw json.RawMessage) json.RawMessage {
324		if raw == nil {
325			return nil
326		}
327		return append(json.RawMessage(nil), raw...)
328	}
329	
330	// isNonEmptyJSONObject reports whether raw is exactly one JSON object with at
331	// least one member. It is shared by HTTP validation and WAL recovery.
332	func isNonEmptyJSONObject(raw json.RawMessage) bool {
333		var value any
334		if json.Unmarshal(raw, &value) != nil {
335			return false
336		}
337		object, ok := value.(map[string]any)
338		return ok && len(object) > 0
339	}
340	
341	// sameJSON compares two JSON documents semantically: object key order and
342	// insignificant whitespace are ignored, numbers compare by value, and array
343	// element order is significant.
344	func sameJSON(a, b json.RawMessage) bool {
345		var av, bv any
346		if json.Unmarshal(a, &av) != nil || json.Unmarshal(b, &bv) != nil {
347			return false
348		}
349		return jsonValueEqual(av, bv)
350	}
351	
352	func jsonValueEqual(a, b any) bool {
353		switch av := a.(type) {
354		case map[string]any:
355			bv, ok := b.(map[string]any)
356			if !ok || len(av) != len(bv) {
357				return false
358			}
359			for key, value := range av {
360				other, ok := bv[key]
361				if !ok || !jsonValueEqual(value, other) {
362					return false
363				}
364			}
365			return true
366		case []any:
367			bv, ok := b.([]any)
368			if !ok || len(av) != len(bv) {
369				return false
370			}
371			for i := range av {
372				if !jsonValueEqual(av[i], bv[i]) {
373					return false
374				}
375			}
376			return true
377		case float64:
378			// Both sides decode through encoding/json, so every JSON number is a
379			// float64; == is the numeric value comparison.
380			bv, ok := b.(float64)
381			return ok && av == bv
382		case string:
383			bv, ok := b.(string)
384			return ok && av == bv
385		case bool:
386			bv, ok := b.(bool)
387			return ok && av == bv
388		case nil:
389			return b == nil
390		default:
391			return false
392		}
393	}
