473	func TestConfigReceiptDedup(t *testing.T) {
474		store, clock := newClockStore()
475		h := NewHandler(store)
476		mustRegister(t, h, "gw")
477		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
478		first := postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusCreated)
479		firstReceived := first.ReceivedAt
480	
481		*clock = clock.Add(time.Hour)
482		// Same receiptId + same content retries with 200 and the first time; it
483		// must not be appended again.
484		retry := postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
485		if !retry.ReceivedAt.Equal(firstReceived) {
486			t.Fatalf("retry receivedAt = %s, want first %s", retry.ReceivedAt, firstReceived)
487		}
488		receipts := listConfigReceipts(t, h, "gw")
489		if len(receipts) != 1 {
490			t.Fatalf("receipts = %d, want 1", len(receipts))
491		}
492	
493		// Same id, different content => 409 in every direction.
494		for _, body := range []string{
495			receiptBody("rc-f", 1, true, ""),
496			receiptBody("rc-f", 1, false, "other"),
497		} {
498			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs/receipts", body); r.Code != http.StatusConflict {
499				t.Fatalf("changed receipt %s => %d, want 409", body, r.Code)
500			}
501		}
502		if receipts := listConfigReceipts(t, h, "gw"); len(receipts) != 1 {
503			t.Fatalf("409 retries changed receipts: %+v", receipts)
504		}
505	
506		// A different receiptId can report the later success.
507		postReceipt(t, h, "gw", receiptBody("rc-ok", 1, true, ""), http.StatusCreated)
508		// Re-reporting the old failure id still retries as 200 (stored first result)
509		// rather than becoming a new conflict against applied state.
510		postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
511	}
